'use strict';
const notes={campus:{title:'Кампус / Ясный ритм',description:'Мягкие формы, чистая иерархия и ясные тематические обложки. Цена, исполнитель и действие легко находятся взглядом. Самая универсальная основа для ежедневного маркетплейса.',motion:'Короткое нажатие 100–140 мс, спокойное раскрытие фильтров 180 мс. Карточки не двигаются при прокрутке.'},editorial:{title:'Студенческий редактор',description:'Тёплая бумага, наборные акценты и более строгая геометрия. Плотнее, выразительнее, ближе к современному студенческому изданию. Карточки построены иначе при том же содержимом.',motion:'Короткое подчёркивание и смещение деталей на 1–2 px. Без перелистывания всей страницы и задержек перед действием.'},orbit:{title:'Орбита / Спокойная глубина',description:'Точная типографика, прохладные поверхности и небольшие геометрические акценты. Глубина создаётся средствами CSS; поиск работает без 3D и WebGPU.',motion:'Небольшая реакция границы и поверхности 140–180 мс. Нет постоянного вращения, параллакса и движения камеры.'}};
let selected='campus';const view=document.querySelector('#view'),theme=document.querySelector('#theme');
function sizeFrames(){const mode=view.value;document.querySelectorAll('.frame-host:not([hidden])').forEach(host=>{const frame=host.querySelector('iframe'),shell=host.querySelector('.frame-shell');const width=(mode==='desktop'||mode==='components')?1440:390,height=(mode==='components'||mode==='desktop')?1000:844;const scale=Math.min(1,(host.clientWidth-2)/width);frame.width=String(width);frame.height=String(height);frame.style.transform=`scale(${scale})`;shell.style.height=`${height*scale}px`;});}
function update(){const mode=view.value;document.querySelector('.preview-area').dataset.view=mode;document.querySelectorAll('[data-concept]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.concept===selected)));document.querySelectorAll('[data-frame]').forEach(host=>{host.hidden=mode!=='all'&&host.dataset.frame!==selected;const frame=host.querySelector('iframe');const src=`${host.dataset.frame}.html?theme=${theme.value}${mode==='components'?'&components=1':''}`;if(frame.getAttribute('src')!==src)frame.src=src;});document.querySelector('.concept-notes h1').textContent=notes[selected].title;document.querySelector('.notes-description').textContent=notes[selected].description;document.querySelector('.notes-motion').textContent=notes[selected].motion;document.querySelector('.open-full').href=`${selected}.html?theme=${theme.value}${mode==='components'?'&components=1':''}`;sizeFrames();}
document.querySelectorAll('[data-concept]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.concept;update();}));view.addEventListener('change',update);theme.addEventListener('change',update);new ResizeObserver(sizeFrames).observe(document.querySelector('.preview-area'));update();
